// Generates src/generated/types.ts and src/generated/operations.ts from the OpenAPI descriptions the Java build publishes
// (docs/api/openapi-*.json; the REST modules' tests write them). No dependencies: a small converter for the subset of OpenAPI
// that springdoc emits for this API.
//
//   node scripts/generate.mjs           rewrite the generated files
//   node scripts/generate.mjs --check   fail when they are out of date (the unit test does the same)

import { readFileSync, readdirSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
export const docsDir = resolve(here, '../../../../docs/api');
export const outDir = resolve(here, '../src/generated');

/** The prefix every path of the published description has; the client's base path replaces it. */
const API_PREFIX = '/api';
const HEADER =
  '// GENERATED by scripts/generate.mjs from docs/api/openapi-*.json - do not edit. Run `npm run generate` after the API changed.\n';

export function readSpecs(directory = docsDir) {
  return readdirSync(directory)
    .filter((name) => /^openapi-.*\.json$/.test(name))
    .sort()
    .map((name) => ({ name, spec: JSON.parse(readFileSync(join(directory, name), 'utf8')) }));
}

/** Merges the descriptions: schemas by name, operations by operationId (the server description repeats core and dev). */
export function merge(specs) {
  const schemas = {};
  const operations = {};
  for (const { name, spec } of specs) {
    for (const [schemaName, schema] of Object.entries(spec.components?.schemas ?? {})) {
      if (schemas[schemaName] && JSON.stringify(schemas[schemaName]) !== JSON.stringify(schema)) {
        throw new Error(`Schema ${schemaName} differs between the OpenAPI files (seen again in ${name})`);
      }
      schemas[schemaName] = schema;
    }
    for (const [path, item] of Object.entries(spec.paths ?? {})) {
      for (const [method, operation] of Object.entries(item)) {
        if (!['get', 'put', 'post', 'delete', 'patch'].includes(method)) {
          continue;
        }
        const id = operation.operationId;
        if (!id) {
          throw new Error(`${method.toUpperCase()} ${path} in ${name} has no operationId`);
        }
        const candidate = { method: method.toUpperCase(), path, operation };
        if (operations[id] && (operations[id].method !== candidate.method || operations[id].path !== candidate.path)) {
          throw new Error(`operationId ${id} names two different operations (${name})`);
        }
        operations[id] = candidate;
      }
    }
  }
  return { schemas, operations };
}

function refName(ref) {
  return ref.substring(ref.lastIndexOf('/') + 1);
}

/** TypeScript for a schema object. */
export function typeOf(schema, indent = '') {
  if (!schema || Object.keys(schema).length === 0) {
    return 'unknown';
  }
  if (schema.$ref) {
    return refName(schema.$ref);
  }
  if (schema.enum) {
    return schema.enum.map((v) => JSON.stringify(v)).join(' | ');
  }
  const types = Array.isArray(schema.type) ? schema.type : [schema.type];
  const parts = types.map((type) => {
    switch (type) {
      case 'string':
        return 'string';
      case 'integer':
      case 'number':
        return 'number';
      case 'boolean':
        return 'boolean';
      case 'null':
        return 'null';
      case 'array':
        return `${wrap(typeOf(schema.items, indent))}[]`;
      case 'object':
      case undefined:
        return objectType(schema, indent);
      default:
        throw new Error(`Unsupported schema type ${type}`);
    }
  });
  return parts.join(' | ');
}

function wrap(type) {
  return /[|&]/.test(type) ? `(${type})` : type;
}

function objectType(schema, indent) {
  const properties = schema.properties ?? {};
  const names = Object.keys(properties);
  if (names.length === 0) {
    if (schema.additionalProperties && typeof schema.additionalProperties === 'object') {
      return `Record<string, ${typeOf(schema.additionalProperties, indent)}>`;
    }
    return 'Record<string, unknown>';
  }
  const required = new Set(schema.required ?? []);
  const lines = names.map((name) => {
    const optional = required.has(name) ? '' : '?';
    return `${indent}  ${/^[A-Za-z_$][\w$]*$/.test(name) ? name : JSON.stringify(name)}${optional}: ${typeOf(properties[name], `${indent}  `)};`;
  });
  return `{\n${lines.join('\n')}\n${indent}}`;
}

export function generateTypes(schemas) {
  const out = [HEADER];
  for (const name of Object.keys(schemas).sort()) {
    const schema = schemas[name];
    // JsonNode (Jackson's tree) has no properties: any JSON value
    if (name === 'JsonNode') {
      out.push('/** Any JSON value. */\nexport type JsonNode = unknown;\n');
      continue;
    }
    const body = typeOf(schema);
    out.push(body.startsWith('{') ? `export interface ${name} ${body}\n` : `export type ${name} = ${body};\n`);
  }
  return out.join('\n');
}

function responseOf(operation) {
  const responses = operation.responses ?? {};
  const code = Object.keys(responses).find((c) => c.startsWith('2'));
  const response = code ? responses[code] : undefined;
  const content = response?.content;
  if (!content) {
    return { kind: 'none', type: undefined };
  }
  const [, entry] = Object.entries(content)[0];
  const schema = entry.schema;
  // a string (the BPMN XML, a resource's bytes) is read as text
  if (!schema || schema.type === 'string') {
    return { kind: 'text', type: 'string' };
  }
  return { kind: 'json', type: typeOf(schema) };
}

export function generateOperations(operations) {
  const out = [
    HEADER,
    "export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';\n",
    '/** One endpoint of the API: what the client needs to call it. */',
    'export interface OperationSpec {',
    '  readonly method: HttpMethod;',
    '  /** Path below the base path, with {name} placeholders. */',
    '  readonly path: string;',
    '  readonly pathParams: readonly string[];',
    '  readonly queryParams: readonly { readonly name: string; readonly array: boolean; readonly required: boolean }[];',
    '  readonly hasBody: boolean;',
    "  /** How the response is read: `json`, `text` (the body as text) or `none` (no body). */",
    "  readonly response: 'json' | 'text' | 'none';",
    '  readonly tag: string;',
    '  readonly summary: string;',
    '}\n',
    'export const operations = {',
  ];
  for (const id of Object.keys(operations).sort()) {
    const { method, path, operation } = operations[id];
    if (!path.startsWith(`${API_PREFIX}/`)) {
      throw new Error(`${path} is not below ${API_PREFIX}`);
    }
    const parameters = operation.parameters ?? [];
    const pathParams = parameters.filter((p) => p.in === 'path').map((p) => p.name);
    const queryParams = parameters
      .filter((p) => p.in === 'query')
      .map((p) => ({ name: p.name, array: p.schema?.type === 'array', required: Boolean(p.required) }));
    const response = responseOf(operation);
    out.push(`  ${id}: {`);
    out.push(`    method: '${method}',`);
    out.push(`    path: '${path.substring(API_PREFIX.length)}',`);
    out.push(`    pathParams: ${JSON.stringify(pathParams)},`);
    out.push(
      `    queryParams: [${queryParams.map((q) => `{ name: '${q.name}', array: ${q.array}, required: ${q.required} }`).join(', ')}],`,
    );
    out.push(`    hasBody: ${operation.requestBody ? 'true' : 'false'},`);
    out.push(`    response: '${response.kind}',`);
    out.push(`    tag: ${JSON.stringify((operation.tags ?? [''])[0])},`);
    out.push(`    summary: ${JSON.stringify(operation.summary ?? '')},`);
    out.push('  },');
  }
  out.push('} as const satisfies Record<string, OperationSpec>;\n');
  out.push('export type OperationId = keyof typeof operations;\n');
  return out.join('\n');
}

export function generateAll(directory = docsDir) {
  const { schemas, operations } = merge(readSpecs(directory));
  return { 'types.ts': generateTypes(schemas), 'operations.ts': generateOperations(operations) };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const files = generateAll();
  if (process.argv.includes('--check')) {
    let stale = false;
    for (const [name, content] of Object.entries(files)) {
      let current = '';
      try {
        current = readFileSync(join(outDir, name), 'utf8');
      } catch {
        // missing
      }
      if (current !== content) {
        console.error(`src/generated/${name} is out of date: run npm run generate`);
        stale = true;
      }
    }
    process.exit(stale ? 1 : 0);
  }
  mkdirSync(outDir, { recursive: true });
  for (const [name, content] of Object.entries(files)) {
    writeFileSync(join(outDir, name), content);
    console.log(`wrote src/generated/${name}`);
  }
}
